code.solution:
def pass_rate(cases):
    if not cases:
        return 0.0
    passed = 0
    for case in cases:
        text = case['output'].lower()
        if all(k.lower() in text for k in case['must_include']):
            passed += 1
    return round(passed / len(cases), 2)
